$phones$, E'\r?\n+') AS value
),
new_clients AS (
    SELECT DISTINCT phone
    FROM imported i
    WHERE phone IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM clients c
        WHERE CASE
            WHEN regexp_replace(c.phone, '[^0-9]', '', 'g') ~ '^[0-9]{10}$' THEN '7' || regexp_replace(c.phone, '[^0-9]', '', 'g')
            WHEN regexp_replace(c.phone, '[^0-9]', '', 'g') ~ '^8[0-9]{10}$' THEN '7' || substr(regexp_replace(c.phone, '[^0-9]', '', 'g'), 2)
            WHEN regexp_replace(c.phone, '[^0-9]', '', 'g') ~ '^[0-9]{11}$' THEN regexp_replace(c.phone, '[^0-9]', '', 'g')
            ELSE regexp_replace(c.phone, '[^0-9]', '', 'g')
        END = regexp_replace(i.phone, '[^0-9]', '', 'g')
    )
)
INSERT INTO clients (first_name, last_name, phone, status, source)
SELECT
    'Импорт',
    'Клиент 3 ' || LPAD(ROW_NUMBER() OVER (ORDER BY phone)::text, 4, '0'),
    phone,
    'NEW',
    'base3.xlsx'
FROM new_clients;
